#include <map>
#include <vector>

// n — размер data, k — число записей результата.
// Поиск и обход: O(log(n+1) + k).
// Добавление k int — O(k) амортизированно.
// Все операции успешны; вход не меняется.
std::vector<int> Slice(const std::map<int, int>& data, int lo, int hi) {
  std::vector<int> result;
  if (lo >= hi) return result;
  auto first = data.upper_bound(lo);
  const auto last = data.upper_bound(hi);
  for (; first != last; ++first) result.push_back(first->second);
  return result;
}
